// ─────────────────────────────────────────────────────────────
// Supabase getAll returns ONE item PER ROW.
// Use $items() to collect ALL rows from multi-row nodes.
// ─────────────────────────────────────────────────────────────

const session = $node["Fetch Session1"]?.json || {};
const resume  = $node["Fetch Resume"]?.json    || {};
const jd      = $node["Fetch JD"]?.json        || {};

const questionRows   = ($items("Fetch Questions1") || []).map(i => i.json);
const answerRows     = ($items("Fetch Answers1")   || []).map(i => i.json);
const proctoringRows = ($items("Fetch Proctoring1") || []).map(i => i.json);

// Build question lookup
const questionMap = {};
questionRows.forEach(q => { questionMap[q.id] = q; });

// Build answer list for the LLM
const answerList = answerRows.map(a => ({
  question: questionMap[a.question_id]?.question_text || 'Unknown',
  answer:   a.answer_text || 'No answer provided',
  type:     questionMap[a.question_id]?.question_type || 'technical'
}));

// ─── Build structured proctoring summary ───────────────────
const criticalEvents = proctoringRows.filter(e => e.severity === 'critical');
const warningEvents  = proctoringRows.filter(e => e.severity === 'warning');

const countByType = {};
proctoringRows.forEach(e => {
  countByType[e.event_type] = (countByType[e.event_type] || 0) + 1;
});

// Risk level based on critical event count
let proctoringRisk = 'low';
if (criticalEvents.length >= 5 || proctoringRows.length >= 20) proctoringRisk = 'high';
else if (criticalEvents.length >= 2 || warningEvents.length >= 5) proctoringRisk = 'medium';

// Pick the most notable events (critical first, up to 10)
const notableEvents = [
  ...criticalEvents,
  ...warningEvents
].slice(0, 10).map(e => ({
  type:      e.event_type,
  severity:  e.severity,
  timestamp: e.timestamp
}));

const proctoringSummary = {
  total_events:    proctoringRows.length,
  critical_count:  criticalEvents.length,
  warning_count:   warningEvents.length,
  risk_level:      proctoringRisk,
  by_type:         countByType,
  notable_events:  notableEvents
};
// ────────────────────────────────────────────────────────────

return [{
  json: {
    session_id:        session.id,
    candidate_id:      session.candidate_id,
    answers:           answerList,
    totalQuestions:    answerList.length,
    proctoringSummary,
    resumeText:        resume.raw_text || '',
    jdText:            jd.raw_text     || '',
    scoredAt:          new Date().toISOString()
  }
}];

